referenceSolutions.javascript:
export function combinationSum(candidates          , target        )             {
  const choices=[...candidates].sort((a,b)=>a-b), result           =[]; function visit(start       ,remaining       ,path         )      { if(remaining===0) { result.push([...path]);return; } for(let i=start;i<choices.length&&choices[i]<=remaining;i++) { path.push(choices[i]);visit(i,remaining-choices[i],path);path.pop(); } } visit(0,target,[]);return result;
}

